import{_ as t,c as a,a0 as s,o as r}from"./chunks/framework.BGabeMLJ.js";const p=JSON.parse('{"title":"Guide: Run Your First Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user/run-your-first-analysis.md","filePath":"guide/user/run-your-first-analysis.md"}'),o={name:"guide/user/run-your-first-analysis.md"};function n(i,e,l,d,c,h){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="guide-run-your-first-analysis" tabindex="-1">Guide: Run Your First Analysis <a class="header-anchor" href="#guide-run-your-first-analysis" aria-label="Permalink to &quot;Guide: Run Your First Analysis&quot;">​</a></h1><p>This guide is for data analysts and researchers who want to use the FLAME platform. It provides a step-by-step instruction on how to start an analysis and view the results through the <strong>FLAME Hub</strong>. By the end of this guide, you will have successfully executed a sample analysis and be ready to develop your own analysis scripts.</p><div class="info custom-block"><p class="custom-block-title">FLAME Core Concept</p><p>FLAME follows a <strong>Code to Data</strong> approach: You can run your analysis scripts on datasets stored at various university hospitals or institutions, while the sensitive patient records stay in their protected environment. FLAME sends your script to the <strong>nodes</strong> (the local environments at each site) and only aggregated results are returned.</p></div><p><strong>🧬 HALTA Demo:</strong> In this guide, we use HALTA as an example. HALTA is a federated pipeline for Long COVID research that collects local statistics (like age and symptom distributions) and trains a machine learning model on each node. These local results are then aggregated into global plots and statistics. The analysis code and synthetic sample data are provided on <a href="https://github.com/PrivateAIM/Herrsching2026/tree/master" target="_blank" rel="noreferrer">GitHub</a>.</p><h2 id="_1-access-to-the-hub" tabindex="-1">1. Access to the Hub <a class="header-anchor" href="#_1-access-to-the-hub" aria-label="Permalink to &quot;1. Access to the Hub&quot;">​</a></h2><p>The <strong>Hub</strong> is the central web portal where you manage your projects, upload analysis scripts and download the final results. There are two ways to get access:</p><ul><li><strong>Your Institution</strong>: If FLAME is already installed at your institution, please contact your Node Admin for an account.</li><li><strong>Test Instance</strong>: To explore the platform first, you can use our test instance. Please reach out to the administrators via <a href="https://discord.com/invite/yCTX7ePnhb" target="_blank" rel="noreferrer">Discord</a> for access.</li></ul><h2 id="_2-the-analysis-workflow" tabindex="-1">2. The Analysis Workflow <a class="header-anchor" href="#_2-the-analysis-workflow" aria-label="Permalink to &quot;2. The Analysis Workflow&quot;">​</a></h2><h3 id="step-1-create-a-project-proposal" tabindex="-1">Step 1: Create a Project Proposal <a class="header-anchor" href="#step-1-create-a-project-proposal" aria-label="Permalink to &quot;Step 1: Create a Project Proposal&quot;">​</a></h3><p>Before starting an analysis, you need to create a <strong>project</strong>. A project contains all analyses related to your research topic. At this stage, you select the nodes that are eligible to participate in your study. For the detailed process, see <a href="./project.html">Submitting a Project Proposal</a>.</p><p><strong>🧬 HALTA Demo:</strong> For this example, create a project for the topic &quot;Long COVID Research&quot;. Select Node X and Node Y, as these nodes already contain the necessary demo data for this analysis.</p><p>🤝 <strong>Node Admin required:</strong> After submission, the Node Admins of the selected institutions must approve the project before you can proceed.</p><h3 id="step-2-data-preparation" tabindex="-1">Step 2: Data Preparation <a class="header-anchor" href="#step-2-data-preparation" aria-label="Permalink to &quot;Step 2: Data Preparation&quot;">​</a></h3><p>Next, you need to ensure that the required data is available on the respective nodes. Depending on the institution&#39;s infrastructure, your data can be provided in different ways:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Data Store</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FHIR Server</strong></td><td style="text-align:left;">Institutions can connect a FHIR server to FLAME. This allows you to work directly with patient records in the standardized FHIR format within your script.</td></tr><tr><td style="text-align:left;"><strong>Object Storage</strong></td><td style="text-align:left;">If you have your data in structured files like CSV or Parquet, these can be saved in an object storage bucket.</td></tr></tbody></table><p><strong>🧬 HALTA Demo:</strong> If you are running the test analysis, the required demo data is already distributed across the nodes. You can review the expected data format and structure on <a href="https://github.com/PrivateAIM/Herrsching2026/tree/master/data" target="_blank" rel="noreferrer">GitHub</a>.</p><p>🤝 <strong>Node Admin required (for real projects):</strong> For security reasons, only Node Admins can manage data. Please coordinate with your Node Admin to ensure that the necessary data is prepared and linked to your project before you launch your analysis script.</p><h3 id="step-3-start-the-analysis" tabindex="-1">Step 3: Start the Analysis <a class="header-anchor" href="#step-3-start-the-analysis" aria-label="Permalink to &quot;Step 3: Start the Analysis&quot;">​</a></h3><p>Once your project is approved and the data is ready, you can start your analysis in the Hub. After the execution is complete, your results will be available for download. For a step-by-step walkthrough, please see <a href="./analysis.html">Starting an Analysis</a>.</p><p><strong>🧬 HALTA Demo:</strong></p><ul><li><strong>Code:</strong> Download the analysis script <code>analysis.py</code> from <a href="https://github.com/PrivateAIM/Herrsching2026/blob/master/analysis/analysis.py" target="_blank" rel="noreferrer">GitHub</a> and use it as the analysis code.</li><li><strong>Image:</strong> Select a base image containing the required libraries, e.g. Group: <code>python</code>, Image: <code>ml</code></li><li><strong>Entrypoint:</strong> Choose <code>analysis.py</code> as the entrypoint.</li></ul><p>🤝 <strong>Node Admin required:</strong> The analysis starts once all participating nodes have approved the script and triggered the execution manually.</p><p><em>Note: A deployed analysis cannot be edited. If you need to modify your script, simply create a new analysis within your project.</em></p><h2 id="_3-write-your-own-analysis" tabindex="-1">3. Write Your Own Analysis <a class="header-anchor" href="#_3-write-your-own-analysis" aria-label="Permalink to &quot;3. Write Your Own Analysis&quot;">​</a></h2><p>Now that you are familiar with the FLAME workflow, you can begin developing your own analysis pipelines.</p><h3 id="learn-the-basics-sdk" tabindex="-1">Learn the Basics (SDK) <a class="header-anchor" href="#learn-the-basics-sdk" aria-label="Permalink to &quot;Learn the Basics (SDK)&quot;">​</a></h3><p>To write a script that is compatible with FLAME, you need to understand how it handles data distribution and aggregation.</p><p>You can start with the <a href="./analysis-coding.html">Analysis Coding Guide</a>, which explains how to implement your logic using the <code>StarAnalyzer</code> class for local node processing and the <code>StarAggregator</code> class for aggregating the results.</p><h3 id="test-locally" tabindex="-1">Test Locally <a class="header-anchor" href="#test-locally" aria-label="Permalink to &quot;Test Locally&quot;">​</a></h3><p>We recommend testing your scripts locally before uploading them to the Hub. This allows you to iterate and debug quickly on your own machine without waiting for node approvals at each step.</p><p>You can use the FLAME Python Core SDK (specifically tools like <code>StarModelTester</code> or <code>ProxyModelTester</code>) to simulate a federated environment using synthetic data.</p><p>Refer to the <a href="./local-testing.html">Local Testing Guide</a> for detailed instructions.</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p>We provide a variety of example analyses in our documentation. You can find examples for both <a href="./coding_examples/survival-regression.html">actual production scripts</a> and <a href="./testing_examples/local-testing-logistic-regression-example.html">local simulation testing</a>.</p>',34)]))}const y=t(o,[["render",n]]);export{p as __pageData,y as default};
